void cl_wrap_CefView(zval* rv, CefView* p) {
  if (!p) { ZVAL_NULL(rv); return; }
  {
    CefRefPtr<CefBrowserView> cl_child = p->AsBrowserView();
    if (cl_child) { cl_wrap_CefBrowserView(rv, cl_child.get()); return; }
  }
  {
    CefRefPtr<CefButton> cl_child = p->AsButton();
    if (cl_child) { cl_wrap_CefButton(rv, cl_child.get()); return; }
  }
  {
    CefRefPtr<CefPanel> cl_child = p->AsPanel();
    if (cl_child) { cl_wrap_CefPanel(rv, cl_child.get()); return; }
  }
  {
    CefRefPtr<CefScrollView> cl_child = p->AsScrollView();
    if (cl_child) { cl_wrap_CefScrollView(rv, cl_child.get()); return; }
  }
  {
    CefRefPtr<CefTextfield> cl_child = p->AsTextfield();
    if (cl_child) { cl_wrap_CefTextfield(rv, cl_child.get()); return; }
  }
  object_init_ex(rv, ce_CefView);
  cl::LibObject* cl_o = cl::lib_from(Z_OBJ_P(rv));
  cl_o->up[0] = static_cast<CefView*>(p);
  cl_o->ptr = p;
  p->AddRef();
}

